  if (/\bENH\b|\bENHANCED\s+RISK\b/.test(source)) return "ENHANCED";
  if (/\bSLGT\b|\bSLIGHT\s+RISK\b/.test(source)) return "SLIGHT";
  if (/\bMRGL\b|\bMARGINAL\s+RISK\b/.test(source)) return "MARGINAL";
